import re

_VERSION = re.compile(r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)")


def bump(version, part):
    match = _VERSION.fullmatch(version)
    if match is None:
        raise ValueError("invalid version: %r" % (version,))
    major, minor, patch = (int(g) for g in match.groups())
    if part == "major":
        return "%d.0.0" % (major + 1)
    if part == "minor":
        return "%d.%d.0" % (major, minor + 1)
    if part == "patch":
        return "%d.%d.%d" % (major, minor, patch)
    raise ValueError("unknown part: %r" % (part,))

def _parse(version):
    if not isinstance(version, str):
        raise ValueError("invalid version")
    pieces = version.split(".")
    if len(pieces) != 3:
        raise ValueError("invalid version")
    numbers = []
    for piece in pieces:
        if piece == "" or any(c not in "0123456789" for c in piece):
            raise ValueError("invalid version")
        if len(piece) > 1 and piece[0] == "0":
            raise ValueError("invalid version")
        numbers.append(int(piece))
    return numbers


def bump(version, part):
    numbers = _parse(version)
    if part not in ("major", "minor", "patch"):
        raise ValueError("unknown part")
    index = ("major", "minor", "patch").index(part)
    numbers[index] += 1
    for i in range(index + 1, 3):
        numbers[i] = 0
    return ".".join(str(n) for n in numbers)

import re

_PATTERN = re.compile(r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)\Z", re.ASCII)

_BUMPS = {
    "major": lambda a, b, c: (a + 1, 0, 0),
    "minor": lambda a, b, c: (a, b + 1, 0),
    "patch": lambda a, b, c: (a, b, c + 1),
}


def bump(version, part):
    m = _PATTERN.match(version)
    if not m:
        raise ValueError(f"invalid version: {version!r}")
    if part not in _BUMPS:
        raise ValueError(f"unknown part: {part!r}")
    a, b, c = _BUMPS[part](*map(int, m.groups()))
    return f"{a}.{b}.{c}"

